mapper.select:
select * from ( select rownum rnum,a.* from( select c.coach_idx, u.user_idx, u.user_name, c.nickname, c.phone, u.created_at, u.status, (select count(*) from cert c_sub where c_sub.user_idx = c.user_idx and cert_status = '대기') as cert_wait_count from coach c join users u on c.user_idx = u.user_idx
AND ( c.coach_idx LIKE '%' || #{keyword} || '%' OR u.user_name LIKE '%' || #{keyword} || '%' OR c.nickname LIKE '%' || #{keyword} || '%' )
order by cert_wait_count desc, c.coach_idx desc
order by c.coach_idx desc
)a )where rnum between #{start} and #{end}

mapper.update:
update cert 
set cert_name=#{cert_name, jdbcType=VARCHAR}, 
get_date = #{get_date, jdbcType=DATE}, 
cert_from=#{cert_from, jdbcType=VARCHAR}, 
cert_status=#{cert_status, jdbcType=VARCHAR}
where cert_idx=#{cert_idx}

mapper.select:
SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY m.MATCH_IDX DESC) AS rnum, m.MATCH_IDX, CASE WHEN m.MATCH_APPLICANT IS NOT NULL THEN NVL(CASE WHEN m.MATCH_APPLICANT = m.USER1_IDX THEN u1.USER_NAME ELSE u2.USER_NAME END, '(탈퇴회원)') ELSE NVL(CASE WHEN m.CHAT_APPLICANT = m.USER1_IDX THEN u1.USER_NAME ELSE u2.USER_NAME END, '(탈퇴회원)') END AS SENDER, CASE WHEN m.MATCH_APPLICANT IS NOT NULL THEN NVL(CASE WHEN m.MATCH_APPLICANT = m.USER1_IDX THEN u2.USER_NAME ELSE u1.USER_NAME END, '(탈퇴회원)') ELSE NVL(CASE WHEN m.CHAT_APPLICANT = m.USER1_IDX THEN u2.USER_NAME ELSE u1.USER_NAME END, '(탈퇴회원)') END AS RECEIVER, CASE WHEN m.MATCH_APPLICANT IS NOT NULL THEN '매칭신청' ELSE '채팅신청' END AS INITIATOR_TYPE, CASE WHEN s.SCHEDULE_IDX IS NOT NULL THEN '일정확정' WHEN a.AGREEMENT_IDX IS NOT NULL AND a.STATUS = 'Y' THEN '서약완료' WHEN m.IS_MATCH = 'Y' THEN '매칭완료' WHEN m.IS_CHAT = 'Y' THEN '채팅중' ELSE '대기' END AS PROGRESS_STATUS, -- m.CREATED_AT이 없으므로 a.CREATED_AT 또는 SYSDATE(현재시간) 사용 COALESCE(s.START_DATE, a.CREATED_AT, SYSDATE) AS LAST_ACTION_DATE FROM MATCH m LEFT JOIN USERS u1 ON m.USER1_IDX = u1.USER_IDX LEFT JOIN USERS u2 ON m.USER2_IDX = u2.USER_IDX LEFT JOIN AGREEMENT a ON ( (m.USER1_IDX = a.WRITER_IDX AND m.USER2_IDX = a.RECEIVER_IDX) OR (m.USER1_IDX = a.RECEIVER_IDX AND m.USER2_IDX = a.WRITER_IDX) ) LEFT JOIN ( SELECT * FROM ( SELECT SCHEDULE_IDX, AGREEMENT_IDX, START_DATE, ROW_NUMBER() OVER (PARTITION BY AGREEMENT_IDX ORDER BY SCHEDULE_IDX DESC) as rk FROM SCHEDULE ) WHERE rk = 1 ) s ON a.AGREEMENT_IDX = s.AGREEMENT_IDX
(u1.USER_NAME LIKE '%' || #{keyword} || '%' OR u2.USER_NAME LIKE '%' || #{keyword} || '%')
) WHERE rnum BETWEEN #{start} AND #{end}
